input.new_string:
/** Buckets guarding the unauthenticated endpoints. */
const REGISTER_BUCKET = "auth:register";
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/** The workspace name is always `<display name>'s workspace`. */
const WORKSPACE_SUFFIX = "'s workspace";

/**
 * Shortens the display name, never the suffix, so a name near the org
 * schema's length limit still produces a workspace name that fits — and the
 * workspace settings form can save it later without a length error.
 */
function workspaceName(displayName: string): string {
  const full = `${displayName}${WORKSPACE_SUFFIX}`;
  if (full.length <= ORG_NAME_MAX_LENGTH) return full;

  const truncated = displayName.slice(
    0,
    ORG_NAME_MAX_LENGTH - WORKSPACE_SUFFIX.length,
  );
  return `${truncated}${WORKSPACE_SUFFIX}`;
}

/**
 * The first workspace's slug, derived from the display name: a reserved slug
 * or one shorter than the minimum length is never used, falling back to
 * `workspace` instead. `createOrganization` still runs the result through
 * `uniqueSlug()` to resolve collisions.
 */
function workspaceSlugBase(displayName: string): string {
  const candidate = slugify(displayName);
  if (candidate.length < SLUG_MIN_LENGTH || isReservedSlug(candidate)) {
    return "workspace";
  }
  return candidate;
}

